arguments.newString:
# This Managed Node Group is used for Spark benchmark workloads that rely on EBS-backed storage (e.g., r6g, r7g, r8g instances).
    # Scale up the min_size and desired_size before running benchmarks.
    spark_benchmark_ebs = {
      name        = "spark-benchmark-ebs"
      description = "Spark benchmark Managed Node Group for EBS-backed instances"
      # Filtering only Secondary CIDR private subnets starting with "100.". Subnet IDs where the nodes/node groups will be provisioned
      subnet_ids = [element(compact([for subnet_id, cidr_block in zipmap(module.vpc.private_subnets, module.vpc.private_subnets_cidr_blocks) :
        substr(cidr_block, 0, 4) == "100." ? subnet_id : null]), 0)
      ]

      min_size     = 0
      desired_size = 0
      max_size     = 8

      # Use "AL2023_x86_64_STANDARD" if you want to run benchmarks on x86_64 based instances (e.g., r6i, r7i, r8i)
      ami_type = "AL2023_ARM_64_STANDARD"

      # Update the instance types based on your benchmark requirements
      instance_types = ["r6g.xlarge", "r7g.xlarge", "r8g.xlarge"] # 4vCPU - 32GB

      labels = {
        WorkerType    = "ON_DEMAND"
        NodeGroupType = "spark_benchmark_ebs"
      }

      # This block device is used only for root volume. Adjust volume according to your size.
      # NOTE: Don't use this volume for Spark workloads
      block_device_mappings = {
        xvda = {
          device_name = "/dev/xvda"
          ebs = {
            volume_size = 100
            volume_type = "gp3"
          }
        }
        # EBS-backed storage for Spark workloads. Adjust the volume size according to your benchmark requirements.
        xvdb = {
          device_name = "/dev/xvdb"
          ebs = {
            volume_size = 300
            volume_type = "gp3"
          }
        }
      }

      tags = {
        Name          = "spark-benchmark-ebs"
        WorkerType    = "ON_DEMAND"
        NodeGroupType = "spark_benchmark_ebs"
      }
    }

    # This Managed Node Group is used for Spark benchmark workloads that rely on NVMe/SSD instance storage (e.g., r6gd, r7gd, c7gd instances).
    # NVMe instance store volumes are automatically enumerated and assigned a device, so no EBS block device mappings are added here.
    # Scale up the min_size and desired_size before running benchmarks.
    spark_benchmark_ssd = {
      name        = "spark-benchmark-ssd"
      description = "Spark benchmark Managed Node Group for NVMe/SSD-backed instances"
      # Filtering only Secondary CIDR private subnets starting with "100.". Subnet IDs where the nodes/node groups will be provisioned
      subnet_ids = [element(compact([for subnet_id, cidr_block in zipmap(module.vpc.private_subnets, module.vpc.private_subnets_cidr_blocks) :
        substr(cidr_block, 0, 4) == "100." ? subnet_id : null]), 0)
      ]

      min_size     = 0
      desired_size = 0
      max_size     = 8

      # Use "AL2023_x86_64_STANDARD" if you want to run benchmarks on x86_64 based instances (e.g., r6id, r7id, c6id)
      ami_type = "AL2023_ARM_64_STANDARD"

      # Update the instance types based on your benchmark requirements. All "d" type instances use NVMe SSD instance storage.
      instance_types = ["r6gd.xlarge", "r7gd.xlarge", "c7gd.xlarge"] # 4vCPU - 32GB - 1 x 118 NVMe SSD

      labels = {
        WorkerType    = "ON_DEMAND"
        NodeGroupType = "spark_benchmark_ssd"
      }

      tags = {
        Name          = "spark-benchmark-ssd"
        WorkerType    = "ON_DEMAND"
        NodeGroupType = "spark_benchmark_ssd"
      }
    }
  }
}

